import OpenAI from 'openai';
const client = new OpenAI({ baseURL: 'https://api.groq.com/openai/v1' });
export const categorize = (line: string) => client.chat.completions.create({ model: 'openai/gpt-oss-20b', messages: [{ role: 'user', content: line }] });

